      nclexTraps: ["Ubrogepant is acute therapy only; do not schedule it as daily prevention.", "A second dose is separated by at least 2 hours so exposure from the first dose can be assessed and the 200-mg daily ceiling preserved.", "Strong CYP3A inhibition is a contraindication, not merely a suggestion to watch for nausea."],
      populationRisks: [{ type: "pregnancy", label: "Pregnancy and lactation", note: "Human pregnancy data are inadequate and a pregnancy registry is available. Lactation data identify low milk transfer, but infant effects are not fully established." }, { type: "pediatric", label: "Pediatric use", note: "Safety and effectiveness under age 18 have not been established." }, { type: "geriatric", label: "Older adults", note: "No age-only adjustment is established, but older adults were underrepresented; renal, hepatic, vascular, sedation, and polypharmacy risks deserve closer review." }],
